// Same-origin, browser only. Anything that needs a session during SSR goes
// through `useRequestFetch()`, which reaches Nitro without leaving the process.
export const authClient = createAuthClient();

import { drizzleAdapter } from "better-auth/adapters/drizzle";
import { betterAuth } from "better-auth";
import { db, schema } from "@nuxthub/db";

const productionUrl = process.env.BETTER_AUTH_URL?.trim();

export const auth = betterAuth({
  baseURL: productionUrl,
  secret: [REDACTED],
  trustedOrigins: productionUrl ? [productionUrl] : undefined,
  database: drizzleAdapter(db, {
    provider: "pg",
    schema,
  }),
  emailAndPassword: {
    enabled: true,
  },
});

export default defineNuxtRouteMiddleware(async (to) => {
  if (to.path === "/login") {
    return;
  }

  // Goes through Nitro in-process during SSR, so it needs no absolute origin and
  // is not stopped by deployment protection the way a self-addressed HTTP call is.
  const session = await useRequestFetch()("/api/auth/get-session")
    .catch(() => null);

  if (!session) {
    return navigateTo({
      path: "/login",
      query: { redirect: to.fullPath },
    });
  }
});

