import { getProfileWithUser } from "~~/server/utils/profile";
import { requireSessionUserId } from "~~/server/utils/session";

export default defineEventHandler(async (event) => {
  const userId = await requireSessionUserId(event);
  const profile = await getProfileWithUser(userId);

  if (!profile) {
    throw createError({
      statusCode: 404,
      statusMessage: "User not found",
    });
  }

  return { profile };
});

import type { H3Event } from "h3";

export function requireInternalRequest(event: H3Event) {
  const secret = [REDACTED];

  if (!secret) {
    throw createError({
      statusCode: 503,
      statusMessage: "Internal API is not configured",
    });
  }

  const authorization = [REDACTED], "authorization");
  if (authorization !== `Bearer ${secret}`) {
    throw createError({
      statusCode: 401,
      statusMessage: "Unauthorized",
    });
  }
}

import { createThreadBodySchema } from "~~/server/schemas/threads";
import { createThreadForUser } from "~~/server/utils/threads";
import { requireSessionUserId } from "~~/server/utils/session";

export default defineEventHandler(async (event) => {
  const userId = await requireSessionUserId(event);
  const body = await readValidatedBody(event, createThreadBodySchema.parse);
  const thread = await createThreadForUser(userId, body);
  setResponseStatus(event, 201);
  return { thread };
});
